import json, re

with open('/home/user/project/radial.html') as f:
    html = f.read()

# Extract the JSON spec embedded in the page
m = re.search(r'vegaEmbed\(.*?,\s*(\{.*\})\s*,', html, re.DOTALL)
if m:
    spec = json.loads(m.group(1))
    # Print dataset from the spec
    def find_values(obj, path=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                find_values(v, path + '.' + k)
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                find_values(v, path + f'[{i}]')
        else:
            if path.endswith('.source') or path.endswith('.visits'):
                print(f'{path} = {obj}')
    find_values(spec)
